"""Persist a report generated by the business layer."""

from layers.output.document_writer import DocumentWriter


class OutputLayer:
    def __init__(self, output_dir="Result/onboarding_result"):
        self.document_writer = DocumentWriter(output_dir=output_dir)

    def process(self, business_data):
        document = business_data.get("document", "")
        if not isinstance(document, str) or not document.strip():
            return {"success": False, "error": "The business layer did not provide a document"}
        saved = self.document_writer.save_document(document)
        if saved["status"] != "success":
            return {"success": False, "error": saved.get("error")}
        return {"success": True, "filepath": saved["path"],
                "test_case_id": business_data.get("test_case_id", "")}


__all__ = ["OutputLayer"]

